import{_ as s,l as n,o as e,c as i,v as t,p as l,x as o,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"代数数据类型与模式匹配编译","description":"","frontmatter":{"title":"代数数据类型与模式匹配编译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/adt-pattern-compile.md","filePath":"cs/adt-pattern-compile.md","lastUpdated":1789023840000}'),h={name:"cs/adt-pattern-compile.md"};function m(u,a,_,A,f,E){const r=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="代数数据类型与模式匹配编译" tabindex="-1">代数数据类型与模式匹配编译 <a class="header-anchor" href="#代数数据类型与模式匹配编译" aria-label="Permalink to &quot;代数数据类型与模式匹配编译&quot;">​</a></h1><div class="epigraph"><p>和类型是带标签的不交并，积类型是字段。模式匹配应编译成对标签的判定树，而不是层层 `if` 的朴素展开。</p><footer>—— 据 Augustsson, Compiling Pattern Matching, 1985；Peyton Jones, The Implementation of Functional Programming Languages；Appel 整理</footer></div><p>上一课<a href="/cs/typeclass-dictionary">类型类</a>解决操作的重载。缺口是<strong>数据</strong>：代数数据类型（ADT）<code>data T = A Int | B</code> 与模式匹配。主干类型检查有结构体/联合的表面；本课钉标签、装箱与匹配编译。穷尽性下一课专门查；本课假定人写的子句先能编成树。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>朴素：每条子句从上到下尝试，失败回溯。指数与重复测试。Augustsson / Peyton Jones：按列选构造子，生成 switch（或跳表），再递归编译子模式。缺口是<strong>判定树</strong>，不是再定义和类型的引入消去（那是 STLC 的延伸，Pierce 有和与积）。</p><p>表示：空构造子可只留标签；一个指针字段可与标签一起编码（如 GHC 的指针标记）。这是运行时，影响匹配的比较方式。</p><h3 id="模式不是正则词法" tabindex="-1">模式不是正则词法 <a class="header-anchor" href="#模式不是正则词法" aria-label="Permalink to &quot;模式不是正则词法&quot;">​</a></h3><p>模式在值的树上匹配，有绑定与嵌套。不要用 lex 的最长匹配当模式语义。守卫（guard）是匹配成功后的布尔，失败则下一条——判定树要留失败边。</p><p><span class="marginnote">Augustsson 1985。Peyton Jones 的实现书。Maranget 的论文同时服务编译与后课穷尽性。Appel 的 ML 章有短实现。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把子句矩阵化：列是参数位置。选列：构造子种类多的、或能立刻失败的。生成：对已知标签分派；通配与变量推迟绑定。变量绑定变成对字段的投影。</p>',11)),(e(),l(c,null,{default:o(()=>[p(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CL%5B%22%E5%AD%90%E5%8F%A5%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20COL%5B%22%E9%80%89%E5%88%97%22%5D%0A%20%20COL%20--%3E%20SW%5B%22%E6%8C%89%E6%9E%84%E9%80%A0%E5%AD%90%E5%88%86%E6%B4%BE%22%5D%0A%20%20SW%20--%3E%20SUB%5B%22%E5%AD%90%E7%9F%A9%E9%98%B5%E9%80%92%E5%BD%92%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/syntax-directed-translation">SDT</a>：前端把 <code>match</code> 建成核心 case 树；本课是中端前的 lowering。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>共享失败：多条子句的默认边可合并。惰性语言还要考虑匹配的严格性（哪一列先求值），这会改变未定义行为与异常顺序——Haskell 有规则；严格语言简单些。</p><p>不要把嵌套模式降成用户层的 <code>if</code> 链还声称已优化；判定树才是编译。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GADT 的细化类型。后课默认：match 降为标签分派树。下一课穷尽与无用子句诊断。</p><p>也不把面向对象的 visitor 当 ADT 的唯一实现；visitor 是另一编码（表达式问题的另一侧）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ADT = 标签和 + 字段积；匹配编译成判定树。</li><li>子句矩阵按列分派，避免朴素回溯。</li><li>表示（标签、指针标记）影响比较。</li><li>出处：Augustsson, 1985；Peyton Jones；对照 Appel。</li></ul>',9))])}const P=s(h,[["render",m]]);export{g as __pageData,P as default};
